"""
apply.py — executes all system configuration changes for BulwarkOS OOBE.

Each step is a self-contained function returning (success: bool, message: str).
Steps are run sequentially; a failure is recorded but does not abort later steps
unless they have a hard dependency (noted inline).

All commands that modify system state use pkexec / polkit for privilege escalation
rather than requiring the wizard itself to run as root.
"""

import os
import subprocess
import shutil
from pathlib import Path
from typing import Callable

from ..state import WizardState


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

STATE_FILE = "/var/lib/bulwarkos/.setup-complete"
MODPROBE_CONF = "/etc/modprobe.d/bulwarkos-vfio.conf"
DRACUT_CONF = "/etc/dracut.conf.d/bulwarkos-vfio.conf"
VM_TEMPLATE_DIR = "/usr/share/bulwarkos/vm-templates"

# Canonical virsh invocation used by all steps.
# --connect qemu:///system  — always targets the system libvirt instance
#                             explicitly, regardless of the calling user's
#                             default URI, so domains and networks are
#                             registered system-wide (needed for autostart
#                             at boot before any user session exists).
# pkexec                    — required because the wizard runs as a normal
#                             user whose libvirt group membership won't be
#                             active until after the reboot at end of setup.
_VIRSH = ["pkexec", "virsh", "--connect", "qemu:///system"]


def _run(cmd: list[str], timeout: int = 120) -> tuple[bool, str]:
    """Run a command, return (success, output/error)."""
    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            timeout=timeout,
        )
        if result.returncode == 0:
            return True, result.stdout.strip()
        return False, (result.stderr or result.stdout).strip()
    except subprocess.TimeoutExpired:
        return False, f"Command timed out after {timeout}s: {' '.join(cmd)}"
    except FileNotFoundError:
        return False, f"Command not found: {cmd[0]}"


def _write_file_as_root(path: str, content: str) -> tuple[bool, str]:
    """
    Write a file to a system path using a small pkexec helper script.
    In production this would use a polkit-protected D-Bus service;
    here we use a tmpfile + pkexec tee approach for simplicity.
    """
    import tempfile
    try:
        with tempfile.NamedTemporaryFile(mode="w", suffix=".conf", delete=False) as tmp:
            tmp.write(content)
            tmp_path = tmp.name
        ok, msg = _run(["pkexec", "cp", tmp_path, path])
        os.unlink(tmp_path)
        if ok:
            _run(["pkexec", "chmod", "644", path])
        return ok, msg
    except OSError as e:
        return False, str(e)


# ---------------------------------------------------------------------------
# Step 1 — kernel arguments (IOMMU)
# ---------------------------------------------------------------------------

def step_kargs(state: WizardState) -> tuple[bool, str]:
    """
    Appends IOMMU kernel arguments to the current rpm-ostree deployment.
    Uses rpm-ostree kargs which takes effect after next reboot.
    """
    vendor = state.hardware.cpu_vendor
    if vendor == "intel":
        iommu_arg = "intel_iommu=on"
    elif vendor == "amd":
        iommu_arg = "amd_iommu=on"
    else:
        return False, f"Unknown CPU vendor '{vendor}' — cannot set IOMMU karg."

    cmd = [
        "pkexec", "rpm-ostree", "kargs",
        f"--append-if-missing={iommu_arg}",
        "--append-if-missing=iommu=pt",
        "--append-if-missing=rd.driver.pre=vfio-pci",
    ]
    return _run(cmd, timeout=60)


# ---------------------------------------------------------------------------
# Step 2 — modprobe.d VFIO config
# ---------------------------------------------------------------------------

def step_modprobe(state: WizardState) -> tuple[bool, str]:
    """
    Writes /etc/modprobe.d/bulwarkos-vfio.conf with the PCI IDs of all
    devices selected for passthrough (NICs + optional GPU).
    """
    ids: list[str] = []

    for nic in state.selected_nics:
        # vendor_id is already in "xxxx:yyyy" form
        ids.append(nic.vendor_id)

    if state.gpu_passthrough and state.selected_gpu:
        ids.append(state.selected_gpu.vendor_id)
        gpu_driver = state.selected_gpu.driver
    else:
        gpu_driver = None

    if not ids:
        return False, "No PCI devices selected for passthrough."

    unique_ids = list(dict.fromkeys(ids))  # deduplicate, preserve order
    ids_str = ",".join(unique_ids)

    lines = [
        "# BulwarkOS VFIO passthrough configuration",
        "# Generated by BulwarkOS OOBE wizard — do not edit manually",
        "# To reconfigure, run: bulwarkos-setup",
        "",
        f"options vfio-pci ids={ids_str}",
        "",
        "# Ensure vfio-pci binds before other drivers",
        "softdep vfio-pci pre: vfio",
    ]

    if gpu_driver and gpu_driver == "nvidia":
        lines += [
            "",
            "# Prevent Nvidia driver from claiming the GPU before vfio-pci",
            "softdep nvidia pre: vfio-pci",
            "softdep nvidia* pre: vfio-pci",
        ]
    elif gpu_driver and gpu_driver == "amdgpu":
        lines += [
            "",
            "softdep amdgpu pre: vfio-pci",
        ]

    content = "\n".join(lines) + "\n"
    return _write_file_as_root(MODPROBE_CONF, content)


# ---------------------------------------------------------------------------
# Step 3 — dracut / initramfs
# ---------------------------------------------------------------------------

def step_initramfs(state: WizardState) -> tuple[bool, str]:
    """
    Writes /etc/dracut.conf.d/bulwarkos-vfio.conf and triggers an
    initramfs rebuild via rpm-ostree initramfs --enable.
    """
    dracut_content = "\n".join([
        "# BulwarkOS VFIO initramfs configuration",
        "# Generated by BulwarkOS OOBE wizard",
        "",
        'add_drivers+=" vfio vfio_iommu_type1 vfio_pci "',
        'force_drivers+=" vfio-pci "',
        "",
    ])

    ok, msg = _write_file_as_root(DRACUT_CONF, dracut_content)
    if not ok:
        return False, f"Failed to write dracut config: {msg}"

    # Trigger initramfs rebuild embedded in the ostree deployment
    cmd = [
        "pkexec", "rpm-ostree", "initramfs",
        "--enable",
        "--arg=--add-drivers",
        "--arg=vfio vfio_pci vfio_iommu_type1",
    ]
    return _run(cmd, timeout=180)


# ---------------------------------------------------------------------------
# Step 4 — Configure /etc/libvirt/qemu.conf (user/group + libvirtd restart)
# ---------------------------------------------------------------------------

QEMU_CONF = "/etc/libvirt/qemu.conf"

# These are the two lines we need to set (commented out by default in stock
# qemu.conf, defaulting to "qemu"/"qemu"). We uncomment them and substitute
# the signed-in user's username so QEMU processes run under their UID/GID,
# which means disk images in /var/lib/bulwarkos/images/ are accessible and
# virsh/virt-manager launched as that user can fully manage running domains.
_QEMU_CONF_USER_RE  = r'^#?\s*user\s*=\s*"[^"]*"'
_QEMU_CONF_GROUP_RE = r'^#?\s*group\s*=\s*"[^"]*"'


def _get_current_username() -> str:
    """
    Returns the name of the user who launched the wizard.
    os.getlogin() can fail in some session types (e.g. via su/sudo),
    so we fall back through a chain of environment variables and pwd.
    """
    import pwd

    # SUDO_USER is set when the user used sudo — gives original username
    for env_var in ("SUDO_USER", "DBUS_SESSION_BUS_ADDRESS", "USER", "LOGNAME"):
        val = os.environ.get(env_var, "")
        if env_var == "SUDO_USER" and val:
            return val
        if env_var in ("USER", "LOGNAME") and val and val != "root":
            return val

    # Fall back to the real UID from the process credentials
    try:
        return pwd.getpwuid(os.getuid()).pw_name
    except KeyError:
        return "qemu"  # safe default — leaves behaviour unchanged


def step_configure_qemu(state: WizardState) -> tuple[bool, str]:
    """
    Edits /etc/libvirt/qemu.conf to set the QEMU process user and group to
    the signed-in user, then restarts libvirtd so the change takes effect
    before the network and VM definition steps run.

    Two lines are targeted (both commented out by default):
        #user = "qemu"    →  user = "<username>"
        #group = "qemu"   →  group = "<username>"

    The edit is done with a line-by-line regex substitution that:
      - handles the line whether it is currently commented out or not
      - preserves every other line in the file exactly as-is
      - writes back atomically via a temp file + pkexec mv

    A backup is written to /etc/libvirt/qemu.conf.bulwark.bak before any
    change is made, so the original can be restored if needed.
    """
    import re
    import tempfile

    username = _get_current_username()

    # --- Read current file ---------------------------------------------------
    read_ok, content = _run(
        ["pkexec", "cat", QEMU_CONF],
        timeout=10,
    )
    if not read_ok:
        return False, f"Could not read {QEMU_CONF}: {content}"

    # --- Backup original (idempotent — only write if backup doesn't exist) ---
    backup_path = QEMU_CONF + ".bulwark.bak"
    _run(["pkexec", "bash", "-c",
          f'[ -f "{backup_path}" ] || cp "{QEMU_CONF}" "{backup_path}"'],
         timeout=10)

    # --- Substitute user and group lines -------------------------------------
    new_lines: list[str] = []
    user_set  = False
    group_set = False

    for line in content.splitlines():
        if re.match(_QEMU_CONF_USER_RE, line):
            new_lines.append(f'user = "{username}"')
            user_set = True
        elif re.match(_QEMU_CONF_GROUP_RE, line):
            new_lines.append(f'group = "{username}"')
            group_set = True
        else:
            new_lines.append(line)

    # If the lines weren't found at all (very unusual), append them
    if not user_set:
        new_lines.append(f'user = "{username}"')
    if not group_set:
        new_lines.append(f'group = "{username}"')

    new_content = "\n".join(new_lines) + "\n"

    # --- Write new content via temp file + pkexec mv -------------------------
    try:
        with tempfile.NamedTemporaryFile(
            mode="w", suffix=".conf", prefix="bulwark-qemu-", delete=False
        ) as tmp:
            tmp.write(new_content)
            tmp_path = tmp.name
    except OSError as e:
        return False, f"Failed to write temp file: {e}"

    ok, msg = _run(["pkexec", "mv", tmp_path, QEMU_CONF], timeout=10)
    if not ok:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        return False, f"Failed to install new qemu.conf: {msg}"

    ok, msg = _run(["pkexec", "chmod", "644", QEMU_CONF], timeout=10)
    if not ok:
        return False, f"qemu.conf written but chmod failed: {msg}"

    # --- Also ensure the user is in the libvirt group ------------------------
    # This lets virt-manager and virsh work without sudo for this user.
    _run(["pkexec", "usermod", "-aG", "libvirt", username], timeout=15)
    _run(["pkexec", "usermod", "-aG", "kvm",     username], timeout=15)

    # --- Restart libvirtd so the new user/group takes effect -----------------
    ok, msg = _run(
        ["pkexec", "systemctl", "restart", "libvirtd.service"],
        timeout=30,
    )
    if not ok:
        return False, (
            f"qemu.conf updated for user '{username}', but libvirtd "
            f"failed to restart: {msg}"
        )

    return True, f"QEMU configured to run as '{username}'; libvirtd restarted."


# ---------------------------------------------------------------------------
# Step 5 — libvirt network definitions (virsh net-define + net-start)
# ---------------------------------------------------------------------------

# Networks that must exist before any VM can start.
# Order matters: bulwark-internal must exist before sys-net is defined,
# bulwark-appvms must exist before sys-firewall and AppVMs are defined.
_NETWORKS = [
    "net-bulwark-internal",
    "net-bulwark-appvms",
]


def step_define_networks(state: WizardState) -> tuple[bool, str]:
    """
    Defines and auto-starts the two BulwarkOS libvirt bridge networks:

      bulwark-internal  — isolated /30 between sys-net and sys-firewall
      bulwark-appvms    — isolated /24 between sys-firewall and all AppVMs

    Both use forward mode='none' (no host NAT, no host participation).
    Marks both networks as autostart so they persist across host reboots.
    """
    template_dir = Path(VM_TEMPLATE_DIR)
    errors: list[str] = []

    for net_template in _NETWORKS:
        template_path = template_dir / f"{net_template}.xml"
        if not template_path.exists():
            errors.append(f"Network template not found: {net_template}.xml")
            continue

        # Extract the logical network name from the filename
        # e.g. "net-bulwark-internal" → "bulwark-internal"
        net_name = net_template.removeprefix("net-")

        # Check whether the network already exists (idempotent re-runs)
        check_ok, _ = _run(_VIRSH + ["net-info", net_name], timeout=10)
        if check_ok:
            # Already defined — ensure it's active and set to autostart
            _run(_VIRSH + ["net-start", net_name], timeout=15)
            _run(_VIRSH + ["net-autostart", net_name], timeout=10)
            continue

        # Define the network from the template XML
        ok, msg = _run(_VIRSH + ["net-define", str(template_path)], timeout=30)
        if not ok:
            errors.append(f"virsh net-define {net_name}: {msg}")
            continue

        # Start it immediately (so VMs defined in the next step can reference it)
        ok, msg = _run(_VIRSH + ["net-start", net_name], timeout=15)
        if not ok:
            errors.append(f"virsh net-start {net_name}: {msg}")
            continue

        # Mark as autostart so it comes up automatically after every host reboot
        ok, msg = _run(_VIRSH + ["net-autostart", net_name], timeout=10)
        if not ok:
            errors.append(f"virsh net-autostart {net_name}: {msg}")

    if errors:
        return False, "\n".join(errors)
    return True, f"Defined and started {len(_NETWORKS)} network(s)."


# ---------------------------------------------------------------------------
# Step 5 — VM domain definitions (virsh define)
# ---------------------------------------------------------------------------

def _render_template(template_path: Path, replacements: dict[str, str]) -> str:
    """Simple token substitution for libvirt XML templates."""
    content = template_path.read_text()
    for key, value in replacements.items():
        content = content.replace(f"{{{{{key}}}}}", value)
    return content


def step_define_vms(state: WizardState) -> tuple[bool, str]:
    """
    Calls virsh define for sys-net, sys-firewall, and each selected AppVM.
    Template XML files live in /usr/share/bulwarkos/vm-templates/.
    """
    template_dir = Path(VM_TEMPLATE_DIR)
    errors: list[str] = []

    # Build NIC passthrough XML fragment
    nic_hostdevs = ""
    for nic in state.selected_nics:
        addr = nic.pci_address  # e.g. "0000:05:00.0"
        parts = addr.split(":")
        domain = parts[0]
        bus_func = parts[2].split(".")
        bus = parts[1]
        slot = bus_func[0]
        function = bus_func[1]
        nic_hostdevs += f"""
    <hostdev mode='subsystem' type='pci' managed='yes'>
      <source>
        <address domain='0x{domain}' bus='0x{bus}' slot='0x{slot}' function='0x{function}'/>
      </source>
    </hostdev>"""

    # GPU passthrough XML fragment
    gpu_hostdev = ""
    if state.gpu_passthrough and state.selected_gpu:
        addr = state.selected_gpu.pci_address
        parts = addr.split(":")
        domain = parts[0]
        bus_func = parts[2].split(".")
        bus = parts[1]
        slot = bus_func[0]
        function = bus_func[1]
        gpu_hostdev = f"""
    <hostdev mode='subsystem' type='pci' managed='yes'>
      <source>
        <address domain='0x{domain}' bus='0x{bus}' slot='0x{slot}' function='0x{function}'/>
      </source>
    </hostdev>"""

    # VMs to define: always sys-net + sys-firewall, then selected AppVMs
    vm_configs = [
        ("sys-net", {"NIC_HOSTDEVS": nic_hostdevs}),
        ("sys-firewall", {}),
    ]
    for appvm in state.selected_appvms:
        vm_configs.append((appvm, {}))
    if state.gpu_passthrough and state.selected_gpu:
        vm_configs.append(("gaming-vm", {"GPU_HOSTDEV": gpu_hostdev}))

    import tempfile

    for vm_name, replacements in vm_configs:
        template_path = template_dir / f"{vm_name}.xml"
        if not template_path.exists():
            errors.append(f"Template not found: {vm_name}.xml")
            continue

        try:
            xml = _render_template(template_path, replacements)
        except OSError as e:
            errors.append(f"Failed to read template {vm_name}.xml: {e}")
            continue

        with tempfile.NamedTemporaryFile(
            mode="w", suffix=".xml", prefix=f"bulwark-{vm_name}-", delete=False
        ) as tmp:
            tmp.write(xml)
            tmp_path = tmp.name

        ok, msg = _run(_VIRSH + ["define", tmp_path])
        os.unlink(tmp_path)
        if not ok:
            errors.append(f"virsh define {vm_name}: {msg}")

    if errors:
        return False, "\n".join(errors)
    return True, f"Defined {len(vm_configs)} VM(s) successfully."


# ---------------------------------------------------------------------------
# Step 5 — Flatpak installs
# ---------------------------------------------------------------------------

ALWAYS_INSTALL = [
    "org.gnome.Epiphany",
    "org.gnome.World.Secrets",
    "org.gnome.Nautilus",
]

GAMING_FLATPAKS = [
    "com.valvesoftware.Steam",
    "net.lutris.Lutris",
]

LOOKING_GLASS_FLATPAK = "com.github.gnome_looking_glass.LookingGlass"


def step_flatpaks(state: WizardState) -> tuple[bool, str]:
    """Install selected Flatpaks from Flathub."""
    to_install = list(ALWAYS_INSTALL)

    if state.install_steam:
        to_install.append("com.valvesoftware.Steam")
    if state.install_lutris:
        to_install.append("net.lutris.Lutris")
    if state.install_looking_glass:
        to_install.append(LOOKING_GLASS_FLATPAK)

    # Deduplicate
    to_install = list(dict.fromkeys(to_install))

    ok, msg = _run(
        ["flatpak", "install", "--system", "--noninteractive", "flathub"] + to_install,
        timeout=300,
    )
    return ok, msg



# ---------------------------------------------------------------------------
# Step 6 — Provision disk images (download cloud images + cloud-init ISOs)
# ---------------------------------------------------------------------------

IMAGE_DIR      = "/var/lib/bulwarkos/images"
BASE_IMAGE_DIR = "/usr/share/bulwarkos/base-images"

# Shipped-in-image Alpine NoCloud qcow2 (sys-net, sys-firewall, disposable)
_ALPINE_BASE = f"{BASE_IMAGE_DIR}/alpine-nocloud.qcow2"

# Fedora Cloud Base — downloaded at OOBE time for AppVMs
_FEDORA_VERSION = "41"
_FEDORA_URL = (
    f"https://download.fedoraproject.org/pub/fedora/linux/releases/{_FEDORA_VERSION}/"
    f"Cloud/x86_64/images/"
    f"Fedora-Cloud-Base-Generic-{_FEDORA_VERSION}-1.4.x86_64.qcow2"
)

# Map each VM name to (image_type, disk_size_gb)
#   "alpine-shipped" — thin clone from the pre-built Alpine qcow2 in the OCI image
#   "fedora-clone"   — thin clone from a downloaded Fedora Cloud Base qcow2
#   "blank"          — empty qcow2, user installs OS themselves
_VM_IMAGE_SPEC: dict[str, tuple[str, int]] = {
    "sys-net":      ("alpine-shipped", 8),
    "sys-firewall": ("alpine-shipped", 8),
    "personal":     ("fedora-clone",  40),
    "work":         ("fedora-clone",  60),
    "banking":      ("fedora-clone",  20),
    "development":  ("fedora-clone",  80),
    "media":        ("fedora-clone",  40),
    # Disposable: also cloned from Alpine; overlay is what actually runs
    "disposable":   ("alpine-shipped", 10),
    # Gaming VM: blank — user installs their own OS
    "gaming-vm":    ("blank",          80),
}

# cloud-init user-data for Alpine VMs (sys-net, sys-firewall, disposable)
# The shipped image already has cloud-init installed; this configures the
# instance on first boot: sets hostname, enables IP forwarding + nftables.
_ALPINE_USERDATA = """#cloud-config
hostname: {hostname}
write_files:
  - path: /etc/sysctl.d/99-bulwark-forward.conf
    content: |
      net.ipv4.ip_forward = 1
      net.ipv6.conf.all.forwarding = 1
runcmd:
  - rc-update add nftables default
  - rc-update add sshd default
  - sysctl -p /etc/sysctl.d/99-bulwark-forward.conf
"""

# cloud-init user-data for Fedora AppVMs
_FEDORA_USERDATA = """#cloud-config
hostname: {hostname}
user: bulwark
password: changeme
chpasswd:
  expire: true
ssh_pwauth: false
packages:
  - firewalld
  - bash-completion
runcmd:
  - systemctl enable --now firewalld
"""


def _download_file(url: str, dest: Path, timeout: int = 600) -> tuple[bool, str]:
    """Download url to dest via curl, resuming partial downloads."""
    return _run(
        ["curl", "-L", "-C", "-", "-o", str(dest),
         "--retry", "3", "--retry-delay", "2", url],
        timeout=timeout,
    )


def _make_cloud_init_iso(
    vm_name: str, userdata_template: str, dest_dir: Path
) -> tuple[bool, str, str]:
    """
    Generates a NoCloud cloud-init ISO (cidata volume label) in dest_dir.
    Returns (success, message, iso_path_or_empty).
    Tries genisoimage → mkisofs → xorriso in order.
    """
    import tempfile, shutil

    userdata  = userdata_template.format(hostname=vm_name)
    metadata  = f"instance-id: {vm_name}\nlocal-hostname: {vm_name}\n"
    iso_path  = str(dest_dir / f"{vm_name}-cloud-init.iso")

    try:
        work_dir = Path(tempfile.mkdtemp(prefix=f"bulwark-ci-{vm_name}-"))
        (work_dir / "user-data").write_text(userdata)
        (work_dir / "meta-data").write_text(metadata)
    except OSError as e:
        return False, f"Failed to write cloud-init seed files: {e}", ""

    for tool in ("genisoimage", "mkisofs", "xorriso"):
        if tool == "xorriso":
            cmd = ["xorriso", "-as", "mkisofs",
                   "-output", iso_path, "-volid", "cidata",
                   "-joliet", "-rock", str(work_dir)]
        else:
            cmd = [tool, "-output", iso_path, "-volid", "cidata",
                   "-joliet", "-rock", str(work_dir)]
        ok, msg = _run(cmd, timeout=30)
        if ok:
            shutil.rmtree(work_dir, ignore_errors=True)
            return True, f"cloud-init ISO created for {vm_name}", iso_path

    shutil.rmtree(work_dir, ignore_errors=True)
    return False, "genisoimage/mkisofs/xorriso not found — install genisoimage", ""


def step_provision_images(state: WizardState) -> tuple[bool, str]:
    """
    Provisions per-VM qcow2 disk images and cloud-init ISOs into IMAGE_DIR.

    Alpine VMs (sys-net, sys-firewall, disposable):
      - Cloned as thin qcow2 overlays from the pre-built Alpine NoCloud image
        shipped inside the BulwarkOS OCI image at BASE_IMAGE_DIR.
        No network download required.

    Fedora AppVMs (personal, work, banking, development, media):
      - Fedora Cloud Base qcow2 is downloaded once from Fedora mirrors,
        then each AppVM gets a thin clone at its target size.

    Gaming VM:
      - Blank qcow2 only. User installs their own OS.

    Disposable VM:
      - The clone is further split into a read-only base image and a
        writable overlay; bulwarkos-disposable-reset.service recreates
        the overlay on every shutdown to give a clean slate each boot.
    """
    import tempfile, shutil

    errors: list[str] = []

    # 1. Verify the shipped Alpine base image is present
    alpine_base = Path(_ALPINE_BASE)
    if not alpine_base.exists():
        return False, (
            f"Shipped Alpine base image not found at {_ALPINE_BASE}. "
            f"This file should be part of the BulwarkOS OCI image. "
            f"Re-install or rebuild the image."
        )

    # 2. Create IMAGE_DIR as root
    ok, msg = _run(["pkexec", "mkdir", "-p", IMAGE_DIR], timeout=10)
    if not ok:
        return False, f"Could not create image directory {IMAGE_DIR}: {msg}"

    # 3. Staging area — writable by the wizard user
    stage_dir = Path(tempfile.mkdtemp(prefix="bulwark-images-"))

    # 4. Download Fedora base image if any AppVM needs it
    all_vms = ["sys-net", "sys-firewall"] + list(state.selected_appvms)
    if state.gpu_passthrough and state.selected_gpu:
        all_vms.append("gaming-vm")

    needs_fedora = any(
        _VM_IMAGE_SPEC.get(v, ("blank", 0))[0] == "fedora-clone"
        for v in all_vms
    )
    fedora_cache = stage_dir / "fedora-cloud.qcow2"

    if needs_fedora:
        ok, msg = _download_file(_FEDORA_URL, fedora_cache)
        if not ok:
            errors.append(f"Failed to download Fedora base image: {msg}")
            needs_fedora = False  # degrade gracefully — skip Fedora VMs

    # 5. Create per-VM disk images
    for vm_name in all_vms:
        image_type, size_gb = _VM_IMAGE_SPEC.get(vm_name, ("blank", 20))
        dest_image = stage_dir / f"{vm_name}.qcow2"
        iso_path   = ""

        if image_type == "alpine-shipped":
            # Thin overlay on the shipped read-only base.
            # The base lives in /usr/share/ (immutable layer) — safe to use
            # as a backing file directly because ostree never modifies it
            # in place; updates replace the whole deployment atomically.
            ok, msg = _run(
                ["qemu-img", "create",
                 "-f", "qcow2",
                 "-b", str(alpine_base),
                 "-F", "qcow2",
                 str(dest_image),
                 f"{size_gb}G"],
                timeout=30,
            )
            if not ok:
                errors.append(f"qemu-img create (alpine clone) {vm_name}: {msg}")
                continue

            # Generate cloud-init ISO to configure this instance on first boot
            ci_ok, ci_msg, iso_path = _make_cloud_init_iso(
                vm_name, _ALPINE_USERDATA, stage_dir
            )
            if not ci_ok:
                errors.append(f"cloud-init ISO {vm_name}: {ci_msg}")
                iso_path = ""  # non-fatal — VM boots but won't auto-configure

        elif image_type == "fedora-clone":
            if not needs_fedora or not fedora_cache.exists():
                errors.append(f"Skipping {vm_name}: Fedora base image unavailable")
                continue

            ok, msg = _run(
                ["qemu-img", "create",
                 "-f", "qcow2",
                 "-b", str(fedora_cache),
                 "-F", "qcow2",
                 str(dest_image),
                 f"{size_gb}G"],
                timeout=60,
            )
            if not ok:
                errors.append(f"qemu-img create (fedora clone) {vm_name}: {msg}")
                continue

            ci_ok, ci_msg, iso_path = _make_cloud_init_iso(
                vm_name, _FEDORA_USERDATA, stage_dir
            )
            if not ci_ok:
                errors.append(f"cloud-init ISO {vm_name}: {ci_msg}")
                iso_path = ""

        elif image_type == "blank":
            ok, msg = _run(
                ["qemu-img", "create", "-f", "qcow2",
                 str(dest_image), f"{size_gb}G"],
                timeout=30,
            )
            if not ok:
                errors.append(f"qemu-img create (blank) {vm_name}: {msg}")
                continue

        # 6. Move qcow2 into IMAGE_DIR as root
        final_image = f"{IMAGE_DIR}/{vm_name}.qcow2"
        ok, msg = _run(
            ["pkexec", "mv", str(dest_image), final_image], timeout=30
        )
        if not ok:
            errors.append(f"Failed to install image {vm_name}: {msg}")
            continue
        _run(["pkexec", "chmod", "660", final_image], timeout=10)

        # 7. Move cloud-init ISO into IMAGE_DIR as root
        if iso_path:
            final_iso = f"{IMAGE_DIR}/{vm_name}-cloud-init.iso"
            ok, msg = _run(
                ["pkexec", "mv", iso_path, final_iso], timeout=10
            )
            if ok:
                _run(["pkexec", "chmod", "660", final_iso], timeout=10)
            else:
                errors.append(f"Failed to install cloud-init ISO {vm_name}: {msg}")

    # 8. Disposable VM — split into base + overlay
    #    The plain clone created above becomes the pristine read-only base.
    #    bulwarkos-disposable-reset.service recreates the overlay each shutdown.
    if "disposable" in all_vms and not any("disposable" in e for e in errors):
        base_img    = f"{IMAGE_DIR}/disposable-base.qcow2"
        overlay_img = f"{IMAGE_DIR}/disposable-overlay.qcow2"
        clone_img   = f"{IMAGE_DIR}/disposable.qcow2"

        # Rename the clone → base (it's already in IMAGE_DIR from step 6 above)
        ok, msg = _run(["pkexec", "mv", clone_img, base_img], timeout=10)
        if ok:
            # Create the writable overlay on top of the base
            ok, msg = _run(
                ["pkexec", "qemu-img", "create",
                 "-f", "qcow2",
                 "-b", base_img, "-F", "qcow2",
                 overlay_img],
                timeout=30,
            )
            if ok:
                _run(["pkexec", "chmod", "660", overlay_img], timeout=10)
            else:
                errors.append(f"disposable overlay create: {msg}")
        else:
            errors.append(f"disposable base rename: {msg}")

    shutil.rmtree(stage_dir, ignore_errors=True)

    if errors:
        return False, "\n".join(errors)
    return True, f"Provisioned disk images for {len(all_vms)} VM(s)."

# ---------------------------------------------------------------------------
# Step 6 — Write state file (marks setup as complete)
# ---------------------------------------------------------------------------

def step_mark_complete(state: WizardState) -> tuple[bool, str]:
    """
    Writes /var/lib/bulwarkos/.setup-complete to mark setup as done.

    /var/lib/ is root-owned, so all three operations — creating the directory,
    writing the file, and locking down permissions — go through pkexec.
    The wizard process itself never needs write access to /var/lib/.
    """
    import tempfile

    state_dir = Path(STATE_FILE).parent
    content = (
        f"# BulwarkOS setup completed\n"
        f"cpu_vendor={state.hardware.cpu_vendor}\n"
        f"gpu_passthrough={'1' if state.gpu_passthrough else '0'}\n"
        f"appvms={','.join(state.selected_appvms)}\n"
    )

    # 1. Create /var/lib/bulwarkos/ if it does not exist
    ok, msg = _run(
        ["pkexec", "mkdir", "-p", str(state_dir)],
        timeout=10,
    )
    if not ok:
        return False, f"Could not create state directory {state_dir}: {msg}"

    # 2. Write content to a temp file the wizard CAN write to
    try:
        with tempfile.NamedTemporaryFile(
            mode="w",
            suffix=".tmp",
            prefix="bulwark-state-",
            delete=False,
        ) as tmp:
            tmp.write(content)
            tmp_path = tmp.name
    except OSError as e:
        return False, f"Could not write temporary state file: {e}"

    # 3. Move the temp file into place as root
    ok, msg = _run(
        ["pkexec", "mv", tmp_path, STATE_FILE],
        timeout=10,
    )
    if not ok:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        return False, f"Could not install state file at {STATE_FILE}: {msg}"

    # 4. Lock down permissions — readable by root only.
    #    The ConditionPathExists= check in the systemd unit only needs existence,
    #    not readability, so 600 is fine and prevents unprivileged tampering.
    _run(["pkexec", "chmod", "600", STATE_FILE], timeout=10)
    _run(["pkexec", "chown", "root:root", STATE_FILE], timeout=10)

    return True, f"State file written to {STATE_FILE}."


# ---------------------------------------------------------------------------
# Orchestrator — runs all steps, reports progress via callback
# ---------------------------------------------------------------------------

StepCallback = Callable[[str, str, bool], None]
# callback(step_id, message, success)

STEPS: list[tuple[str, str, Callable]] = [
    ("kargs",      "Writing kernel arguments",              step_kargs),
    ("modprobe",   "Writing VFIO modprobe config",          step_modprobe),
    ("initramfs",  "Rebuilding initramfs",                  step_initramfs),
    # qemu.conf must be set and libvirtd restarted before virsh commands run
    ("qemu_conf",  "Configuring QEMU user/group",           step_configure_qemu),
    # Networks must be defined before VMs — VMs reference them by name
    ("networks",   "Defining libvirt networks",             step_define_networks),
    # Images must exist on disk before virsh define — libvirt validates paths
    ("images",     "Downloading and provisioning images",   step_provision_images),
    ("vms",        "Registering VM definitions",            step_define_vms),
    ("flatpaks",   "Installing Flatpaks",                   step_flatpaks),
    ("complete",   "Marking setup complete",                step_mark_complete),
]


def run_apply(state: WizardState, on_step: StepCallback) -> bool:
    """
    Runs all apply steps in order.
    Calls on_step(step_id, message, success) after each step.
    Returns True if all steps succeeded.
    """
    all_ok = True
    for step_id, label, fn in STEPS:
        on_step(step_id, f"{label}…", None)  # None = in-progress
        try:
            ok, msg = fn(state)
        except Exception as exc:
            ok, msg = False, f"Unexpected error: {exc}"
        if not ok:
            state.apply_errors.append(f"{label}: {msg}")
            all_ok = False
        on_step(step_id, msg, ok)
    return all_ok
